import './VerificationCodeInput.scss'

import React, { useCallback, useEffect, useId, useMemo, useRef } from 'react'
import classNames from 'classnames'

import { useI18nT } from '@webapp/store/system'

const defaultLength = 6
const nonDigitsRegExp = /\D/g

type Props = {
  focusOnMount?: boolean
  hideLabel?: boolean
  label: string
  length?: number
  name?: string
  onChange: (value: string) => void
  value: string
}

const toDigits = (text: string): string[] => text.replaceAll(nonDigitsRegExp, '').split('')

/**
 * One box for each digit of a verification code (e.g. generated by an authenticator app).
 * Typing moves to the next box, Backspace to the previous one; pasting a whole code fills all the boxes.
 *
 * @param {Props} props - The props.
 * @param {boolean} [props.focusOnMount] - True to focus the first box when mounted.
 * @param {boolean} [props.hideLabel] - True to hide the label (e.g. when shown by a form item).
 * @param {string} props.label - Label (i18n key).
 * @param {number} [props.length] - Number of digits.
 * @param {string} [props.name] - Name of the first box.
 * @param {Function} props.onChange - Called with the code (digits only).
 * @param {string} props.value - The code.
 * @returns {React.ReactElement} The verification code input.
 */
export const VerificationCodeInput = (props: Props) => {
  const { focusOnMount = false, hideLabel = false, label, length = defaultLength, name, onChange, value } = props

  const t = useI18nT()
  const inputRefs = useRef<(HTMLInputElement | null)[]>([])
  const digits = useMemo(() => Array.from({ length }, (_, index) => value[index] ?? ''), [length, value])
  // stable id of each box (also used as key)
  const idPrefix = useId()
  const boxIds = useMemo(() => Array.from({ length }, (_, index) => `${idPrefix}-${index}`), [idPrefix, length])

  useEffect(() => {
    if (focusOnMount) {
      inputRefs.current[0]?.focus()
    }
  }, [focusOnMount])

  const focusBox = useCallback(
    (index: number) => {
      const input = inputRefs.current[Math.max(0, Math.min(index, length - 1))]
      input?.focus()
      input?.select()
    },
    [length]
  )

  // writes the given digits starting from the given box and moves the focus after the last one
  const setDigitsFrom = useCallback(
    (startIndex: number, newDigits: string[]) => {
      const updated = [...digits]
      for (const [offset, digit] of newDigits.slice(0, length - startIndex).entries()) {
        updated[startIndex + offset] = digit
      }
      onChange(updated.join('').slice(0, length))
      focusBox(startIndex + newDigits.length)
    },
    [digits, focusBox, length, onChange]
  )

  // a whole code (pasted or autofilled, e.g. "123 456") fills all the boxes, whatever box it was entered in
  const setDigitsEnteredIn = useCallback(
    (index: number, enteredDigits: string[]) => {
      if (enteredDigits.length >= length) {
        setDigitsFrom(0, enteredDigits.slice(-length))
      } else if (enteredDigits.length > 0) {
        setDigitsFrom(index, enteredDigits)
      }
    },
    [length, setDigitsFrom]
  )

  const onInputChange = (index: number) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const newDigits = toDigits(event.target.value)
    // typing in a box with a digit appends the new one: keep only that
    const replacingDigit = newDigits.length === 2 && Boolean(digits[index])
    setDigitsEnteredIn(index, replacingDigit ? newDigits.slice(1) : newDigits)
  }

  const onKeyDown = (index: number) => (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Backspace') {
      event.preventDefault()
      const clearIndex = digits[index] ? index : index - 1
      if (clearIndex < 0) return
      const updated = [...digits]
      updated[clearIndex] = ''
      onChange(updated.join(''))
      focusBox(clearIndex)
    } else if (event.key === 'ArrowLeft') {
      focusBox(index - 1)
    } else if (event.key === 'ArrowRight') {
      focusBox(index + 1)
    }
  }

  const onPaste = (index: number) => (event: React.ClipboardEvent<HTMLInputElement>) => {
    event.preventDefault()
    setDigitsEnteredIn(index, toDigits(event.clipboardData.getData('text')))
  }

  const labelText = t(label)

  return (
    <fieldset className="verification-code-input">
      {/* hidden (but still read by assistive technologies) when the label is shown by the containing form item */}
      <legend className={classNames({ 'verification-code-input__legend--hidden': hideLabel })}>{labelText}</legend>
      <div className="verification-code-input__boxes">
        {boxIds.map((boxId, index) => (
          <input
            key={boxId}
            id={boxId}
            ref={(element) => {
              inputRefs.current[index] = element
            }}
            aria-label={`${labelText} ${index + 1}/${length}`}
            autoComplete={index === 0 ? 'one-time-code' : 'off'}
            inputMode="numeric"
            name={index === 0 ? name : undefined}
            onChange={onInputChange(index)}
            onFocus={(event) => event.target.select()}
            onKeyDown={onKeyDown(index)}
            onPaste={onPaste(index)}
            pattern="[0-9]*"
            type="text"
            value={digits[index]}
          />
        ))}
      </div>
    </fieldset>
  )
}
